local SausageMaker = {}
local PRODUCTS = {
    fresh_pork_sausage = { name = "Sveža svinjska klobasa", porkCost = 2, gutCost = 1, spiceCost = 1, time = 2, cost = 18, flavorStrength = 30, happiness = 2, description = "Sveža svinjska klobasa za peko." },
    beef_sausage = { name = "Goveja klobasa", beefCost = 2, gutCost = 1, spiceCost = 1, time = 3, cost = 45, flavorStrength = 45, happiness = 3, prestige = 1, description = "Goveja klobasa z bogatim okusom." },
    smoked_sausage = { name = "Prekajena klobasa", porkCost = 3, gutCost = 1, spiceCost = 1, fuelCost = 1, time = 5, cost = 110, flavorStrength = 60, happiness = 4, prestige = 3, description = "Prekajena klobasa za dolgo shranjevanje." },
    spiced_hunter_sausage = { name = "Začinjena lovska klobasa", porkCost = 3, beefCost = 1, gutCost = 1, spiceCost = 2, time = 7, cost = 240, flavorStrength = 75, happiness = 5, prestige = 6, description = "Lovska klobasa z močnimi začimbami." },
    silver_cased_sausage = { name = "Srebrno obložena klobasa", porkCost = 4, beefCost = 1, gutCost = 1, silverCost = 1, spiceCost = 2, time = 10, cost = 520, flavorStrength = 90, happiness = 7, prestige = 12, description = "Klobasa s srebrno oblogo za plemiče." },
    royal_grand_sausage = { name = "Kraljevski veliki klobasa", porkCost = 6, beefCost = 3, goldCost = 1, silverCost = 1, jewelCost = 1, gutCost = 2, spiceCost = 3, time = 15, cost = 1500, flavorStrength = 100, happiness = 14, prestige = 35, description = "Velika kraljevska klobasa z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Klobasarska delavnica", cost = { gold = 280, wood = 130, stone = 200 }, upkeep = 7, qualityBonus = 5 },
    sausage_kitchen = { name = "Klobasarna", cost = { gold = 900, wood = 250, stone = 400, pork = 8 }, upkeep = 22, qualityBonus = 18 },
    smoking_room = { name = "Kadilnica", cost = { gold = 2200, wood = 350, stone = 600, silver = 30, fuel = 10 }, upkeep = 55, qualityBonus = 30 },
    royal_sausage_atelier = { name = "Kraljevski atelje klobas", cost = { gold = 9000, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 180, qualityBonus = 55, prestigeBonus = 40 },
}
SausageMaker.porkStock = 22; SausageMaker.beefStock = 16; SausageMaker.gutStock = 14; SausageMaker.spiceStock = 12; SausageMaker.fuelStock = 14; SausageMaker.silverStock = 8; SausageMaker.goldStock = 6; SausageMaker.jewelStock = 6
SausageMaker.productStock = {}; SausageMaker.buildings = {}; SausageMaker.maker = nil; SausageMaker.activeMaking = {}; SausageMaker.totalProducts = 0; SausageMaker.dayTimer = 0
function SausageMaker.init() SausageMaker.porkStock=22; SausageMaker.beefStock=16; SausageMaker.gutStock=14; SausageMaker.spiceStock=12; SausageMaker.fuelStock=14; SausageMaker.silverStock=8; SausageMaker.goldStock=6; SausageMaker.jewelStock=6; SausageMaker.productStock={}; SausageMaker.buildings={}; SausageMaker.maker=nil; SausageMaker.activeMaking={}; SausageMaker.totalProducts=0; SausageMaker.dayTimer=0; print("[SausageMaker] Royal Sausage Maker System initialized (6 products, 4 buildings)") end
function SausageMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SausageMaker.maker={name=n or ("Klobasar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klobasar najet: %s (spretnost: %d)",SausageMaker.maker.name,s),"success") end; return true end
function SausageMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SausageMaker.build(id) local ok,e=SausageMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SausageMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SausageMaker.getQualityBonus() local b=0; for _,bd in ipairs(SausageMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SausageMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.porkCost and SausageMaker.porkStock<(d.porkCost or 0) then return false,"Premalo svinjine" end; if d.beefCost and SausageMaker.beefStock<(d.beefCost or 0) then return false,"Premalo govedine" end; if d.gutCost and SausageMaker.gutStock<(d.gutCost or 0) then return false,"Premalo črevesja" end; if d.spiceCost and SausageMaker.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.fuelCost and SausageMaker.fuelStock<(d.fuelCost or 0) then return false,"Premalo goriva" end; if d.silverCost and SausageMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SausageMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SausageMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SausageMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SausageMaker.maker then return false,"Potreben klobasar" end; return true end
function SausageMaker.make(pt,qty) qty=qty or 5; local ok,e=SausageMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.porkCost then SausageMaker.porkStock=SausageMaker.porkStock-d.porkCost*qty end; if d.beefCost then SausageMaker.beefStock=SausageMaker.beefStock-d.beefCost*qty end; if d.gutCost then SausageMaker.gutStock=SausageMaker.gutStock-d.gutCost*qty end; if d.spiceCost then SausageMaker.spiceStock=SausageMaker.spiceStock-d.spiceCost*qty end; if d.fuelCost then SausageMaker.fuelStock=SausageMaker.fuelStock-d.fuelCost*qty end; if d.silverCost then SausageMaker.silverStock=SausageMaker.silverStock-d.silverCost*qty end; if d.goldCost then SausageMaker.goldStock=SausageMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SausageMaker.jewelStock=SausageMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if SausageMaker.maker then t=math.max(1,t-math.floor(SausageMaker.maker.skill/12)) end; table.insert(SausageMaker.activeMaking,{id="sausage_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,flavorStrength=d.flavorStrength or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SausageMaker.completeMaking(m) local q=1.0+(SausageMaker.getQualityBonus()/100); if SausageMaker.maker then q=q+(SausageMaker.maker.skill/180) end; q=math.min(2.0,q); SausageMaker.productStock[m.productType]=(SausageMaker.productStock[m.productType] or 0)+m.quantity; SausageMaker.totalProducts=SausageMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SausageMaker.maker then SausageMaker.maker.itemsMade=SausageMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then SausageMaker.maker.skill=math.min(100,SausageMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Klobasa izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"sausage.completed",{productName=m.productName,flavorStrength=m.flavorStrength,happiness=m.happiness}) end end
function SausageMaker.update(dt) if not _G.state then return end; SausageMaker.dayTimer=SausageMaker.dayTimer+dt; if SausageMaker.dayTimer>=30 then SausageMaker.dayTimer=0; for i=#SausageMaker.activeMaking,1,-1 do local m=SausageMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SausageMaker.completeMaking(m); table.remove(SausageMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SausageMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SausageMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SausageMaker.getStats() return {porkStock=SausageMaker.porkStock,beefStock=SausageMaker.beefStock,gutStock=SausageMaker.gutStock,spiceStock=SausageMaker.spiceStock,fuelStock=SausageMaker.fuelStock,silverStock=SausageMaker.silverStock,goldStock=SausageMaker.goldStock,jewelStock=SausageMaker.jewelStock,productStock=SausageMaker.productStock,numBuildings=#SausageMaker.buildings,hasMaker=SausageMaker.maker~=nil,makerName=SausageMaker.maker and SausageMaker.maker.name or "—",makerSkill=SausageMaker.maker and SausageMaker.maker.skill or 0,activeMaking=#SausageMaker.activeMaking,totalProducts=SausageMaker.totalProducts} end
return SausageMaker
